+  template <std::size_t... I>
+  static constexpr auto make_table(std::index_sequence<I...>) {
+    return std::array<KernelFn, kMaxMTiles>{tiny_mma_kernel<Trait, I + 1, Out, kUsePDL>...};
+  }
